-- =====================================================================
-- 262 — Lote 2 LNME (3/6): perfis em public.drug_profiles (2/2)
-- ---------------------------------------------------------------------
-- Conteúdo autoral (não copiado), ancorado nos rótulos aprovados
-- DailyMed (setIDs validados na API — nenhum fictício) e corroborado
-- no Prontuário Terapêutico do INFARMED (11.ª ed., 2012).
-- Padrão 7.6: JOIN (VALUES) ON d.slug = v.slug + ON CONFLICT DO NOTHING.
-- Idempotente. Companheiras: 260 (drugs), 261 (perfis 1/2), 263
-- (farmacologia).
-- =====================================================================

INSERT INTO public.drug_profiles
  (drug_id, overview_public_pt, overview_public_en, overview_pro_pt, overview_pro_en,
   indications_pt, indications_en, side_effects_pt, side_effects_en,
   precautions_pt, precautions_en, source_pt, source_en, status)
SELECT d.id, v.overview_public_pt, v.overview_public_en, v.overview_pro_pt, v.overview_pro_en,
       v.indications_pt, v.indications_en, v.side_effects_pt, v.side_effects_en,
       v.precautions_pt, v.precautions_en, v.source_pt, v.source_en, 'published'
FROM public.drugs d
JOIN (VALUES
  ('bupivacaina',
   E'Bupivacaína é um anestésico local de longa duração usado para adormecer partes do corpo durante cirurgias e partos: raquianestesia, bloqueios de nervos e infiltrações. O efeito dura 3–8 horas, muito mais que a lidocaína.',
   E'Bupivacaine is a long-acting local anaesthetic used to numb parts of the body during surgery and childbirth: spinal anaesthesia, nerve blocks and infiltrations. The effect lasts 3–8 hours, much longer than lidocaine.',
   E'Amida lipofílica que bloqueia canais de sódio nervosos com forte preferência pelo estado inativado; dissociação lenta durante a diástole explica a maior cardiotoxicidade comparada à lidocaína (arritmias difíceis de reverter). Início 5–10 min, duração 3–8 h (raquianestesia com tetracaína-like). Dose máxima adulta ~ 2,5 mg/kg (com adrenalina 3 mg/kg), nunca em vasos.',
   E'Lipophilic amide blocking nerve sodium channels with strong preference for the inactivated state; slow dissociation during diastole explains greater cardiotoxicity than lidocaine (arrhythmias difficult to reverse). Onset 5–10 min, duration 3–8 h (spinal). Adult max ~ 2.5 mg/kg (with adrenaline 3 mg/kg), never intravascular.',
   E'• Raquianestesia e epidural (incl. obstétrica)\\n• Bloqueios de nervos periféricos (axilar, femoral, interescalénico)\\n• Infiltração local em cirurgia prolongada\\n• Analgesia pós-operatória contínua (cateter)',
   E'• Spinal and epidural anaesthesia (including obstetric)\\n• Peripheral nerve blocks (axillary, femoral, interscalene)\\n• Local infiltration in prolonged surgery\\n• Continuous post-operative analgesia (catheter)',
   E'• Hipotensão e bradicardia (bloqueio simpático em raqui/epidural)\\n• Retenção urinária transitória\\n• Toxicidade sistémica (LAST): zumbidos, gosto metálico, perioral formigueiro, convulsões, arritmias graves\\n• Lesão nervosa transitória ou permanente (raro)\\n• Procure ajuda imediata se houver convulsões, palpitões ou perda súbita de consciência após o bloqueio.',
   E'• Hypotension and bradycardia (sympathetic block in spinal/epidural)\\n• Transient urinary retention\\n• Systemic toxicity (LAST): tinnitus, metallic taste, perioral tingling, seizures, serious arrhythmias\\n• Transient or permanent nerve injury (rare)\\n• Seek immediate help if seizures, palpitations or sudden loss of consciousness occur after the block.',
   E'• Aspirar antes de injetar e usar dose-teste com adrenalina em grandes volumes\\n• Dose máxima absoluta a respeitar (2,5 mg/kg sem adrenalina)\\n• Ter lipidoemulsão 20% disponível no ambiente de bloqueios\\n• Evitar em bloqueios interescalénicos sem suporte (risco de bloqueio frénico/contralateral)',
   E'• Aspirate before injecting and use an adrenaline test dose with large volumes\\n• Respect the absolute maximum dose (2.5 mg/kg without adrenaline)\\n• Have 20% lipid emulsion available in block settings\\n• Avoid interscalene blocks without support (phrenic/contralateral block risk)',
   E'Rótulo aprovado DailyMed/FDA — Bupivacaine Hydrochloride (ver rótulos de associação: Physicians EZ Use M-PRED valida via CYP; preferir rótulo mono-ingrediente): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=76b15f6a-51d6-45ec-b6cb-8b10a08ed32a — com referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)',
   E'DailyMed/FDA approved label — Bupivacaine Hydrochloride (see combination labels: Physicians EZ Use M-PRED validates via CYP; prefer mono-ingredient label): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=76b15f6a-51d6-45ec-b6cb-8b10a08ed32a — with additional reference: Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012)'),

  ('propofol',
   E'Propofol é o anestésico geral intravenoso mais usado no mundo: a "leite branco" que dorme o doente em segundos antes de cirurgias e procedimentos. Só é administrado por profissionais treinados em anestesia.',
   E'Propofol is the most widely used intravenous general anaesthetic in the world: the "white milk" that puts patients to sleep in seconds before surgeries and procedures. It is only administered by professionals trained in anaesthesia.',
   E'Alquilfenol em emulsão lipídica: modula positivamente o recetor GABA-A, deprimindo o SNC de forma dose-dependente (sedação → anestesia). Início em um braço-giro (~30 s), duração 3–10 min em bolus; clearance hepático elevado permite infusion prolongada com re-despertar rápido. Reduz a resistência vascular sistémica e deprime a respiração; antedoto sem — reversão só por suspensão.',
   E'Alkylphenol in lipid emulsion: positively modulates the GABA-A receptor, dose-dependently depressing the CNS (sedation → anaesthesia). Onset in one arm-brain time (~30 s), 3–10 min duration at bolus; high hepatic clearance allows prolonged infusion with rapid re-awakening. Reduces systemic vascular resistance and depresses respiration; no antidote — reversal only by stopping.',
   E'• Indução e manutenção da anestesia geral\\n• Sedação para procedimentos (endoscopia, cardioversão) em ambiente monitorizado\\n• Sedação em cuidados intensivos (ventilação)\\n• Tratamento refratário de estado epiléptico (uso especializado)',
   E'• Induction and maintenance of general anaesthesia\\n• Procedural sedation (endoscopy, cardioversion) in monitored settings\\n• Intensive care sedation (ventilation)\\n• Treatment of refractory status epilepticus (specialised use)',
   E'• Dor na injeção (frequente; atenuar com lidocaína)\\n• Hipotensão e depressão respiratória (dose-dependentes)\\n• Movimentos mioclónicos e tosse na indução\\n• Síndrome de infusão de propofol (PROF) em infusões > 48 h: acidose, rabdomiólise, insuficiência cardíaca — raro mas letal\\n• Pancreatite (raro)\\n• Procure ajuda imediata se após anestesia houver dor abdominal intensa, fraqueza generalizada ou coração muito lento.',
   E'• Injection pain (frequent; attenuated with lidocaine)\\n• Hypotension and respiratory depression (dose-dependent)\\n• Myoclonic movements and cough at induction\\n• Propofol infusion syndrome (PRIS) in infusions > 48 h: acidosis, rhabdomyolysis, heart failure — rare but lethal\\n• Pancreatitis (rare)\\n• Seek immediate help if intense abdominal pain, generalised weakness or very slow heartbeat occurs after anaesthesia.',
   E'• Ambiente com equipamento de anestesia, via aérea e suporte cardiovascular obrigatório\\n• Higiene asséptica da emulsão (risco de infeção) — usar no prazo de 6 h\\n• Em cuidados intensivos, vigiar triglicéridos e CPK em infusões > 48 h\\n• Reduzir dose em idosos, hipovolémia e classe ASA III–IV',
   E'• Setting with anaesthesia equipment, airway and cardiovascular support mandatory\\n• Aseptic handling of the emulsion (infection risk) — use within 6 h\\n• In ICU, monitor triglycerides and CPK for infusions > 48 h\\n• Reduce dose in the elderly, hypovolaemia and ASA class III–IV',
   E'Rótulo aprovado DailyMed/FDA — Propofol Injection, Emulsion: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=5ec25932-6c21-4cd5-8f60-80761f2e20a6 — com referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)',
   E'DailyMed/FDA approved label — Propofol Injection, Emulsion: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=5ec25932-6c21-4cd5-8f60-80761f2e20a6 — with additional reference: Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012)'),

  ('efedrina',
   E'Efedrina é um medicamento que eleva a tensão arterial e o pulso. É usada sobretudo em anestesias do parto para corrigir quedas de tensão, e em situações de urgência com tensão muito baixa.',
   E'Ephedrine is a medicine that raises blood pressure and pulse. It is mainly used in childbirth anaesthesia to correct blood pressure drops, and in emergency situations with very low blood pressure.',
   E'Simpatomimético de ação mista (direta em adrenoreceptores α/β e indireta por libertação de noradrenalina). Aumento do débito cardíaco e da resistência periférica com mínimo efeito uteroplacentário comparado aos puros α1 — preferido historicamente na hipotensão da raquianestesia obstétrica. Taquifilaxia rápida por depleção de noradrenalina.',
   E'Mixed-action sympathomimetic (direct α/β adrenoceptor action and indirect noradrenaline release). Raises cardiac output and peripheral resistance with minimal uteroplacental effect compared with pure α1 agents — historically preferred in obstetric spinal hypotension. Rapid tachyphylaxis through noradrenaline depletion.',
   E'• Hipotensão da anestesia raquidiana/epidural em obstetrícia\\n• Hipotensão em anestesia geral ou sedação\\n• Bradicardia com hipotensão (alternativa à atropina)\\n• Nasal: descongestionante tópico (uso tópico limitado)',
   E'• Hypotension from spinal/epidural anaesthesia in obstetrics\\n• Hypotension in general anaesthesia or sedation\\n• Bradycardia with hypotension (alternative to atropine)\\n• Nasal: topical decongestant (limited topical use)',
   E'• Taquicardia, palpitações e ansiedade\\n• Hipertensão reflexa (dose excessiva)\\n• Cefaleia, tremor e náuseas\\n• Insónia e agitação\\n• Arritmias em dose alta ou repetida\\n• Procure ajuda imediata se houver dor torácica, palpitações intensas ou cefaleia súbita muito forte.',
   E'• Tachycardia, palpitations and anxiety\\n• Reflex hypertension (excessive dose)\\n• Headache, tremor and nausea\\n• Insomnia and agitation\\n• Arrhythmias at high or repeated dose\\n• Seek immediate help if chest pain, intense palpitations or a very sudden strong headache occurs.',
   E'• Evitar repetir doses em taquifilaxia (eficácia cai rapidamente)\\n• Cuidado em hipertensão, coronariopatia, hipertiroidismo e feocromocitoma\\n• Interação grave com IMAO (crise hipertensiva) — contraindicado\\n• Em obstetrícia, preferir dose mínima eficaz e vigiar fetal',
   E'• Avoid repeated doses in tachyphylaxis (efficacy drops quickly)\\n• Caution in hypertension, coronary disease, hyperthyroidism and phaeochromocytoma\\n• Serious interaction with MAOIs (hypertensive crisis) — contraindicated\\n• In obstetrics, prefer minimum effective dose and monitor the fetus',
   E'Rótulo aprovado DailyMed/FDA — Ephedrine Sulfate Tablet [CVS]: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=e338deef-efad-1d82-e053-2995a90a1bf9 — com referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)',
   E'DailyMed/FDA approved label — Ephedrine Sulfate Tablet [CVS]: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=e338deef-efad-1d82-e053-2995a90a1bf9 — with additional reference: Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012)'),

  ('flumazenil',
   E'Flumazenil é o antídoto dos benzodiazepínicos (diazepam, midazolam). É usado no hospital para acordar doentes com sedação excessiva ou sobredosagem por este tipo de medicamentos.',
   E'Flumazenil is the antidote to benzodiazepines (diazepam, midazolam). It is used in hospital to wake patients with excessive sedation or overdose from this type of medicine.',
   E'Antagonista competitivo do sítio benzodiazepínico do recetor GABA-A: bloqueia os efeitos sedativos, amnésicos e anticonvulsivos dos agonistas. Vida curta (45–90 min) vs. benzodiazepínicos longos (diazepam) → risco de re-sedação. Em dependentes, pode precipitar convulsões e síndrome de abstinência.',
   E'Competitive antagonist at the benzodiazepine site of the GABA-A receptor: blocks the sedative, amnesic and anticonvulsant effects of agonists. Short half-life (45–90 min) vs. long benzodiazepines (diazepam) → re-sedation risk. In dependent patients it can precipitate seizures and withdrawal syndrome.',
   E'• Reversão da sedação por benzodiazepínicos em procedimentos diagnósticos\\n• Sobredosagem isolada por benzodiazepínicos (diagnóstico/terapêutica)\\n• Reversão de sedação em doentes que não ventilar bem',
   E'• Reversal of benzodiazepine sedation in diagnostic procedures\\n• Isolated benzodiazepine overdose (diagnosis/treatment)\\n• Reversal of sedation in patients breathing poorly',
   E'• Agitação, ansiedade e náuseas na reversão brusca\\n• Convulsões (especialmente em dependentes ou tricíclicos associados)\\n• Re-sedação quando o efeito passa (vida curta)\\n• Arritmias e reações de pânico\\n• Procure ajuda imediata se houver convulsões ou dificuldade em respirar.',
   E'• Agitation, anxiety and nausea on abrupt reversal\\n• Seizures (especially in dependent patients or with co-ingested tricyclics)\\n• Re-sedation when the effect wears off (short half-life)\\n• Arrhythmias and panic reactions\\n• Seek immediate help if seizures or breathing difficulty occur.',
   E'• Nunca usar em sobredosagem mista com antidepressivos tricíclicos (risco convulsivo elevado)\\n• Vigiar 2 h após reversão (re-sedação)\\n• Não usar como "despertador" rotineiro — reservar para indicações claras\\n• Ambiente com suporte de via aérea disponível',
   E'• Never use in mixed overdose with tricyclic antidepressants (high seizure risk)\\n• Monitor for 2 h after reversal (re-sedation)\\n• Not a routine "waker" — reserve for clear indications\\n• Setting with airway support available',
   E'Rótulo aprovado DailyMed/FDA — Flumazenil Injection: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=56452ba8-521d-1f84-e063-6294a90af6fc — com referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)',
   E'DailyMed/FDA approved label — Flumazenil Injection: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=56452ba8-521d-1f84-e063-6294a90af6fc — with additional reference: Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012)'),

  ('clonidina',
   E'Clonidina é um medicamento que baixa a tensão arterial agindo no cérebro. É também usado na dor neuropática, na abstinência de opióides e no TDAH (forma de libertação prolongada em alguns países).',
   E'Clonidine is a medicine that lowers blood pressure by acting on the brain. It is also used for neuropathic pain, opioid withdrawal, and ADHD (extended-release form in some countries).',
   E'Agonista central dos recetores alfa-2-adrenérgicos (locus coeruleus e centro vasomotor): reduz a descarga simpática, o débito cardíaco e as resistências periféricas. Reduz também a neurotransmissão nociceptiva espinhal (uso adjuvante na dor). Rebound hipertensivo com interrupção brusca é o risco mais conhecido.',
   E'Central alpha-2 adrenergic agonist (locus coeruleus and vasomotor centre): reduces sympathetic outflow, cardiac output and peripheral resistance. Also reduces spinal nociceptive transmission (adjunctive pain use). Hypertensive rebound on abrupt discontinuation is the best-known risk.',
   E'• Hipertensão arterial (2.ª linha, sobretudo em associação)\\n• Sintomas de abstinência de opióides (clonidina em dose baixa)\\n• Dor neuropática refratária (adjuvante)\\n• Profilaxia de enxaqueca (casos selecionados)',
   E'• Arterial hypertension (second line, mainly in combination)\\n• Opioid withdrawal symptoms (low-dose clonidine)\\n• Refractory neuropathic pain (adjunct)\\n• Migraine prophylaxis (selected cases)',
   E'• Boca seca (muito comum) e sedação\\n• Hipotensão ortostática e bradicardia\\n• Tonturas e obstipação\\n• Rebote hipertensivo na suspensão brusca (cefaleia, taquicardia, sudorese)\\n• Depressão (uso prolongado)\\n• Procure ajuda imediata se após suspender houver cefaleia intensa, palpitações e suores abundantes.',
   E'• Dry mouth (very common) and sedation\\n• Orthostatic hypotension and bradycardia\\n• Dizziness and constipation\\n• Hypertensive rebound on abrupt withdrawal (headache, tachycardia, sweating)\\n• Depression (prolonged use)\\n• Seek immediate help if intense headache, palpitations and abundant sweating occur after stopping.',
   E'• NUNCA suspender bruscamente — reduzir gradualmente (rebote)\\n• Cuidado em idosos (hipotensão ortostática e quedas)\\n• Interação com beta-bloqueantes (rebote agravado na suspensão)\\n• Vigiar pulso e tensão no início do tratamento',
   E'• NEVER stop abruptly — taper gradually (rebound)\\n• Caution in the elderly (orthostatic hypotension and falls)\\n• Interaction with beta-blockers (rebound worsened on withdrawal)\\n• Monitor pulse and blood pressure at treatment start',
   E'Rótulo aprovado DailyMed/FDA — Clonidine Hydrochloride Tablet [Alembic]: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=d90b2ca4-7753-4012-a1b2-fb92bdf0ebb6 — com referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)',
   E'DailyMed/FDA approved label — Clonidine Hydrochloride Tablet [Alembic]: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=d90b2ca4-7753-4012-a1b2-fb92bdf0ebb6 — with additional reference: Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012)'),

  ('nitroprussiato',
   E'Nitroprussiato de sódio é um vasodilatador de ação imediata usado apenas no hospital, por gota a gota, para baixar tensões arteriais muito altas em emergências (urgência hipertensiva, dissecção aórtica).',
   E'Sodium nitroprusside is an immediate-acting vasodilator used only in hospital, by drip, to lower very high blood pressures in emergencies (hypertensive emergency, aortic dissection).',
   E'Doador não enzimático de NO: dilata arteríolas e veias simultaneamente, reduzindo pós-carga e pré-carga. Início em segundos, vida < 2 min → titulação min a min. O metabolismo libera cianeto (convertido a tiocianato renal) — toxicidade por cianeto com infusões > 2 mcg/kg/min prolongadas ou défice de tiosulfato (insuficiência renal/hepática).',
   E'Non-enzymatic NO donor: dilates arterioles and veins simultaneously, reducing afterload and preload. Onset in seconds, half-life < 2 min → minute-by-minute titration. Metabolism releases cyanide (converted to renal thiocyanate) — cyanide toxicity with prolonged infusions > 2 mcg/kg/min or thiosulfate deficiency (kidney/liver failure).',
   E'• Urgência hipertensiva (encefalopatia, eclampsia em ambiente de especialidade)\\n• Dissecção aguda da aorta (com betabloqueante)\\n• Falência ventricular aguda grave (redução de pós-carga)\\n• Controlo de tensão em cirurgia vascular (hipotensão induzida)',
   E'• Hypertensive emergency (encephalopathy, eclampsia in specialist setting)\\n• Acute aortic dissection (with beta-blocker)\\n• Severe acute heart failure (afterload reduction)\\n• Blood pressure control in vascular surgery (induced hypotension)',
   E'• Hipotensão excessiva e reflexa (taquicardia)\\n• Toxicidade por cianeto: acidose láctica, confusão, tinitus, cefaleia, aritmias (infusões prolongadas ou alta dose)\\n• Toxicidade por tiocianato (insuficiência renal): fadiga, mioclonias, convulsões\\n• Metemoglobinemia (raro)\\n• Procure ajuda imediata se durante a perfusão houver confusão, respiração rápida ou convulsões.',
   E'• Excessive hypotension and reflex tachycardia\\n• Cyanide toxicity: lactic acidosis, confusion, tinnitus, headache, arrhythmias (prolonged or high-dose infusions)\\n• Thiocyanate toxicity (renal failure): fatigue, myoclonus, seizures\\n• Methaemoglobinaemia (rare)\\n• Seek immediate help if confusion, rapid breathing or seizures occur during the infusion.',
   E'• EXCLUSIVO em cuidados intensivos com tensão intra-arterial\\n• Não exceder 2 mcg/kg/min por > 3 h sem avaliação de toxicidade\\n• Proteger da luz (aluminio/invólucro opaco)\\n• Não usar em hipertensão por feocromocitoma isolada (preferir fentolamina)',
   E'• ICU ONLY with intra-arterial pressure monitoring\\n• Do not exceed 2 mcg/kg/min for > 3 h without toxicity assessment\\n• Protect from light (aluminium/opaque wrapping)\\n• Not first choice in phaeochromocytoma hypertension (prefer phentolamine)',
   E'Rótulo aprovado DailyMed/FDA — Sodium Nitroprusside Injection: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=5a599880-c133-44ef-a9f2-bd1b681563be — com referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)',
   E'DailyMed/FDA approved label — Sodium Nitroprusside Injection: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=5a599880-c133-44ef-a9f2-bd1b681563be — with additional reference: Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012)'),

  ('heparina',
   E'Heparina é um anticoagulante injetável de ação imediata usado para prevenir e tratar coágulos: trombose venosa profunda, embolia pulmonar, e para manter cateteres e máquinas de diálise sem coagular.',
   E'Heparin is an immediate-acting injectable anticoagulant used to prevent and treat clots: deep vein thrombosis, pulmonary embolism, and to keep catheters and dialysis machines from clotting.',
   E'Glicosaminoglicano que ativa a antitrombina III 1000×: inibição imediata de trombina (IIa) e fator Xa. Vida curta (~90 min IV) → ajuste por TTPa. Pode causar trombocitopenia imune (TIH) tipo 2 — grave e paradoxalmente protrombótica — e osteoporose em uso prolongado. Reversível com protamina.',
   E'Glycosaminoglycan that activates antithrombin III 1000×: immediate inhibition of thrombin (IIa) and factor Xa. Short half-life (~90 min IV) → aPTT-guided adjustment. Can cause immune thrombocytopenia (HIT) type 2 — serious and paradoxically prothrombotic — and osteoporosis with prolonged use. Reversible with protamine.',
   E'• Tratamento agudo de trombose venosa profunda e embolia pulmonar\\n• Anticoagulação em síndrome coronária aguda\\n• Anticoagulação extracorporal (hemodiálise, circulação extracorporal)\\n• Profilaxia de alto risco em hospital (pós-operatório, imobilização)',
   E'• Acute treatment of deep vein thrombosis and pulmonary embolism\\n• Anticoagulation in acute coronary syndrome\\n• Extracorporeal anticoagulation (haemodialysis, cardiopulmonary bypass)\\n• High-risk in-hospital prophylaxis (post-operative, immobilisation)',
   E'• Sangramento (o risco mais frequente): gengivas, urina escura, fezes negras, equimoses\\n• Trombocitopenia (TIH): queda > 50% das plaquetas 5–10 dias após início, com novos coágulos\\n• Osteoporose e fraturas (uso prolongado > 3 meses)\\n• Hiperpotassemia (inibição da aldosterona)\\n• Procure ajuda imediata se houver sangramento abundante, dor súbita de perna ou falta de ar.',
   E'• Bleeding (the most frequent risk): gums, dark urine, black stools, bruising\\n• Thrombocytopenia (HIT): > 50% platelet drop 5–10 days after starting, with new clots\\n• Osteoporosis and fractures (prolonged use > 3 months)\\n• Hyperkalaemia (aldosterone inhibition)\\n• Seek immediate help if there is heavy bleeding, sudden leg pain or shortness of breath.',
   E'• Vigiar TTPa (1,5–2,5× o controlo) em perfusão contínua\\n• Vigiar PLAQUETAS no dia 0, 3, 5 e 7 (detetar TIH)\\n• Suspender e avaliar se TIH suspeita (não trocar por heparina de baixo peso molecular)\\n• Reversão: protamina (parcial)\\n• Cuidado em úlcera ativa, AVC hemorrágico recente e cirurgia recente',
   E'• Monitor aPTT (1.5–2.5× control) on continuous infusion\\n• Monitor PLATELETS on days 0, 3, 5 and 7 (HIT detection)\\n• Stop and evaluate if HIT suspected (do not switch to LMWH)\\n• Reversal: protamine (partial)\\n• Caution in active ulcer, recent haemorrhagic stroke and recent surgery',
   E'Rótulo aprovado DailyMed/FDA — Heparin Sodium Injection [Gland Pharma]: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=301b19bc-21c2-4a35-9d29-569b08d855c4 — com referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)',
   E'DailyMed/FDA approved label — Heparin Sodium Injection [Gland Pharma]: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=301b19bc-21c2-4a35-9d29-569b08d855c4 — with additional reference: Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012)'),

  ('dopamina',
   E'Dopamina é um medicamento de urgência usado no hospital para elevar a tensão arterial e melhorar o funcionamento do coração em doentes em choque grave (por infeção, coração fraco ou perda de sangue).',
   E'Dopamine is an emergency medicine used in hospital to raise blood pressure and improve heart function in patients in severe shock (from infection, weak heart or blood loss).',
   E'Precursor da noradrenalina com efeito dose-dependente: dose baixa (2–5 mcg/kg/min) predomina dopaminérgico (vasodilatação renal/mesentérica); dose média (5–10) β1-cardíaco (inotropismo); dose alta (> 10) α-vasoconstritor. Liberada como agonista indireto (dependente de reservas de noradrenalina). Titulação por tensão invasiva; extravasamento causa necrose cutânea.',
   E'Noradrenaline precursor with dose-dependent effect: low dose (2–5 mcg/kg/min) dopaminergic predominance (renal/mesenteric vasodilation); medium dose (5–10) β1-cardiac (inotropy); high dose (> 10) α-vasoconstrictor. Acts as an indirect agonist (dependent on noradrenaline stores). Titration by invasive pressure; extravasation causes skin necrosis.',
   E'• Choque com hipotensão refratária a volume (sepsis, cardiogénico)\\n• Bradicardia sintomática refratária a atropina (alternativa temporária)\\n• Suporte inotrópico em insuficiência cardíaca aguda',
   E'• Shock with hypotension refractory to volume (sepsis, cardiogenic)\\n• Symptomatic bradycardia refractory to atropine (temporary alternative)\\n• Inotropic support in acute heart failure',
   E'• Taquiarritmias (frequentes em dose média/alta)\\n• Vasoconstrição periférica extrema e isquemia de membros em dose alta\\n• Necrose cutânea por extravasamento (risco sério)\\n• Hipertensão e cefaleia\\n• Náuseas e vómitos\\n• Procure ajuda imediata se o local da perfusão ficar branco, doloroso ou frio.',
   E'• Tachyarrhythmias (frequent at medium/high doses)\\n• Extreme peripheral vasoconstriction and limb ischaemia at high dose\\n• Skin necrosis from extravasation (serious risk)\\n• Hypertension and headache\\n• Nausea and vomiting\\n• Seek immediate help if the infusion site turns white, painful or cold.',
   E'• Perfusão em veia central sempre que possível (evitar extravasamento)\\n• Ter fentolamina local disponível para extravasamento\\n• Titular pela tensão alvo; não exceder dose sem reavaliar diagnóstico\\n• Cuidado em arritmias prévias e feocromocitoma',
   E'• Central line infusion whenever possible (avoid extravasation)\\n• Have local phentolamine available for extravasation\\n• Titrate to target pressure; do not exceed dose without reassessing diagnosis\\n• Caution in previous arrhythmias and phaeochromocytoma',
   E'Rótulo aprovado DailyMed/FDA — Dopamine Hydrochloride Injection: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=1f306ad2-3606-4525-5a8a-ce78f426c1a2 — com referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)',
   E'DailyMed/FDA approved label — Dopamine Hydrochloride Injection: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=1f306ad2-3606-4525-5a8a-ce78f426c1a2 — with additional reference: Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012)'),

  ('dobutamina',
   E'Dobutamina é um medicamento que faz o coração bater com mais força. É usado no hospital para doentes com insuficiência cardíaca grave ou choque cardíaco, quando o coração não consegue bombear o suficiente.',
   E'Dobutamine is a medicine that makes the heart beat harder. It is used in hospital for patients with severe heart failure or cardiogenic shock, when the heart cannot pump enough.',
   E'Agonista β1-seletivo sintético (racémico) com inotropismo positivo forte e leve cronotropismo; vasodilatação β2 compensa parcialmente a vasoconstrição. Não libera noradrenalina endógena (diferente da dopamina) → útil em doentes sob betabloqueante e na falência com hipotensão leve. Taquifilaxia em 48–72 h.',
   E'Synthetic β1-selective agonist (racemic) with strong positive inotropy and mild chronotropy; β2 vasodilation partially offsets vasoconstriction. Does not release endogenous noradrenaline (unlike dopamine) → useful in patients on beta-blockers and in failure with mild hypotension. Tachyphylaxis within 48–72 h.',
   E'• Insuficiência cardíaca aguda descompensada com baixo débito\\n• Choque cardiogénico (associado a vasopressor se hipotensão marcada)\\n• Teste de stress ecocardiográfico farmacológico (dose baixa, diagnóstico)',
   E'• Acute decompensated heart failure with low output\\n• Cardiogenic shock (combined with vasopressor if marked hypotension)\\n• Pharmacological echocardiographic stress test (low dose, diagnostic)',
   E'• Taquiarritmias (frequentes): extrassístoles, taquicardia, fibrilhação\\n• Hipotensão paradoxal (vasodilatação β2 em alguns doentes)\\n• Isquemia miocárdica por aumento do consumo de oxigénio\\n• Cefaleia, tremor e náuseas\\n• Procure ajuda imediata se houver dor torácica ou palpitações intensas durante a perfusão.',
   E'• Tachyarrhythmias (frequent): extrasystoles, tachycardia, fibrillation\\n• Paradoxical hypotension (β2 vasodilation in some patients)\\n• Myocardial ischaemia from increased oxygen consumption\\n• Headache, tremor and nausea\\n• Seek immediate help if chest pain or intense palpitations occur during the infusion.',
   E'• Monitorização cardíaca contínua e tensão invasiva em choque\\n• Não usar como único vasopressor em hipotensão grave (associar noradrenalina)\\n• Taquifilaxia após 48–72 h → reavaliar necessidade\\n• Cuidado em fibrilhação auricular rápida (acelera resposta ventricular)',
   E'• Continuous cardiac monitoring and invasive pressure in shock\\n• Not the sole vasopressor in severe hypotension (combine with noradrenaline)\\n• Tachyphylaxis after 48–72 h → reassess need\\n• Caution in rapid atrial fibrillation (accelerates ventricular response)',
   E'Rótulo aprovado DailyMed/FDA — Dobutamine in Dextrose Injection: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=559367ef-5c20-99ea-e063-6294a90a4ff2 — com referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)',
   E'DailyMed/FDA approved label — Dobutamine in Dextrose Injection: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=559367ef-5c20-99ea-e063-6294a90a4ff2 — with additional reference: Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012)'),

  ('noradrenalina',
   E'Noradrenalina é o medicamento de primeira linha no choque séptico e nas tensões muito baixas em cuidados intensivos: contrai os vasos para restaurar a tensão arterial mantendo o coração a funcionar.',
   E'Noradrenaline is the first-line medicine in septic shock and very low blood pressures in intensive care: it constricts vessels to restore blood pressure while keeping the heart working.',
   E'Agonista α1 predominante com leve β1: vasoconstrição sistémica intensa com inotropismo moderado e efeito cronotrópico menor que a adrenalina/dopamina. Primeira escolha no choque séptico (mantém a perfusão coronária e renal melhor que dopamina em meta-análises). Vida curta (2 min) → perfusão contínua titulada; extravasamento → necrose.',
   E'Predominant α1 agonist with mild β1: intense systemic vasoconstriction with moderate inotropy and less chronotropy than adrenaline/dopamine. First choice in septic shock (maintains coronary and renal perfusion better than dopamine in meta-analyses). Short half-life (2 min) → titrated continuous infusion; extravasation → necrosis.',
   E'• Choque séptico (primeira linha)\\n• Choque cardiogénico e hipovolémico refratário (com volume)\\n• Hipotensão em anestesia refratária a outras medidas\\n• Choque neurogénico',
   E'• Septic shock (first line)\\n• Cardiogenic and refractory hypovolaemic shock (with volume)\\n• Anaesthesia hypotension refractory to other measures\\n• Neurogenic shock',
   E'• Isquemia de extremidades e pele (vasoconstrição intensa)\\n• Hipertensão reflexa e bradicardia (vagus)\\n• Necrose cutânea por extravasamento (risco sério)\\n• Arritmias e taquicardia (menos que dopamina)\\n• Ansiedade e cefaleia\\n• Procure ajuda imediata se o local da perfusão ficar branco, doloroso ou frio.',
   E'• Limb and skin ischaemia (intense vasoconstriction)\\n• Reflex hypertension and bradycardia (vagal)\\n• Skin necrosis from extravasation (serious risk)\\n• Arrhythmias and tachycardia (less than dopamine)\\n• Anxiety and headache\\n• Seek immediate help if the infusion site turns white, painful or cold.',
   E'• Veia central preferencial (extravasamento grave em periférica)\\n• Ter fentolamina local disponível\\n• Hipovolémia deve ser corrigida antes/durante (não substitui volume)\\n• Em dose > 1 mcg/kg/min, reavaliar diagnóstico e associar inotrópico se necessário',
   E'• Central line preferred (severe extravasation peripherally)\\n• Have local phentolamine available\\n• Hypovolaemia must be corrected before/during (does not replace volume)\\n• At dose > 1 mcg/kg/min, reassess diagnosis and add an inotrope if needed',
   E'Rótulo aprovado DailyMed/FDA — Norepinephrine Bitartrate Injection: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=109aa5e6-4e42-4131-97b0-f24d3a4cb4e8 — com referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)',
   E'DailyMed/FDA approved label — Norepinephrine Bitartrate Injection: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=109aa5e6-4e42-4131-97b0-f24d3a4cb4e8 — with additional reference: Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012)'),

  ('aminofilina',
   E'Aminofilina é um broncodilatador clássico usado em crises de asma e Bronquite que não respondem bem aos inhaladores. É administrado no hospital por injeção ou gota a gota em situações graves.',
   E'Aminophylline is a classic bronchodilator used in asthma and bronchitis attacks that do not respond well to inhalers. It is administered in hospital by injection or drip in severe situations.',
   E'Complexo de teofilina com etilenodiamina: inibe as fosfodiesterases (↑ AMPc broncodilatador), antagoniza adenosina e melhora a força diafragmática. Janela terapêutica estreita (10–20 mcg/mL) → dose guiada por níveis séricos. Metabolismo hepático CYP1A2 variável (tabaco induz, insuficiência cardíaca/hepática e macrólidos reduzem clearance).',
   E'Theophylline–ethylenediamine complex: inhibits phosphodiesterases (↑ bronchodilator cAMP), antagonises adenosine and improves diaphragmatic strength. Narrow therapeutic window (10–20 mcg/mL) → dose guided by serum levels. Hepatic CYP1A2 metabolism variable (smoking induces; heart/liver failure and macrolides reduce clearance).',
   E'• Crise asmática grave / estado de mal asmático (adjuvante dos nebulizados e corticoide)\\n• Exacerbação grave de DPOC com broncospasmo refratário\\n• Apneia do recém-nascido (com teofilina, uso neonatal especializado)',
   E'• Severe asthma attack / status asthmaticus (adjunct to nebulisers and corticosteroid)\\n• Severe COPD exacerbation with refractory bronchospasm\\n• Newborn apnoea (with theophylline, specialised neonatal use)',
   E'• Náuseas, vómitos e dor abdominal (muito comum)\\n• Taquicardia e arritmias\\n• Tremor fino das mãos, inquietação e insónia\\n• Convulsões (sinal de toxicidade grave — pode ocorrer sem sinais prévios)\\n• Cefaleia e diurese\\n• Procure ajuda imediata se houver convulsões, palpitações intensas ou vómitos persistentes durante a perfusão.',
   E'• Nausea, vomiting and abdominal pain (very common)\\n• Tachycardia and arrhythmias\\n• Fine hand tremor, restlessness and insomnia\\n• Seizures (sign of serious toxicity — may occur without prior warning signs)\\n• Headache and diuresis\\n• Seek immediate help if seizures, intense palpitations or persistent vomiting occur during the infusion.',
   E'• Perfusão lenta com monitorização cardíaca (risco arrítmico)\\n• Vigiar níveis séricos em tratamentos > 24 h ou com fatores de risco de acumulação\\n• Cuidado em insuficiência hepática, cardíaca e em idosos (clearance reduzido)\\n• Interação crítica com eritromicina, claritromicina, ciprofloxacina, cimetidina e fluvoxamina (↑ toxicidade)',
   E'• Slow infusion with cardiac monitoring (arrhythmic risk)\\n• Monitor serum levels for treatments > 24 h or with accumulation risk factors\\n• Caution in liver, heart failure and the elderly (reduced clearance)\\n• Critical interaction with erythromycin, clarithromycin, ciprofloxacin, cimetidine and fluvoxamine (↑ toxicity)',
   E'Rótulo aprovado DailyMed/FDA — Aminophylline Injection: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=819207a2-0c37-b275-e053-2a91aa0afb36 — com referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)',
   E'DailyMed/FDA approved label — Aminophylline Injection: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=819207a2-0c37-b275-e053-2a91aa0afb36 — with additional reference: Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012)'),

  ('metilprednisolona',
   E'Metilprednisolona é um cortisona potente usada em inflamações graves: crises de asma, alergias severas, doenças reumáticas e do intestino, e para prevenir rejeição de transplantes. Existe em comprimidos e injeções.',
   E'Methylprednisolone is a potent cortisone used in severe inflammation: asthma attacks, severe allergies, rheumatic and bowel diseases, and to prevent transplant rejection. It comes in tablets and injections.',
   E'Glicocorticoide sintético com potência 5× a hidrocortisona e mínima atividade mineralocorticoide. Liga o recetor intracelular de glicocorticoides, alterando a transcrição génica (↓ IL-1, IL-6, TNF-α; ↑ lipocortina). Vida plasmática curta (2–3 h) mas efeito biológico 12–36 h. A dose em pulso (500–1000 mg IV) é usada em doenças autoimunes graves.',
   E'Synthetic glucocorticoid 5× hydrocortisone potency with minimal mineralocorticoid activity. Binds the intracellular glucocorticoid receptor, altering gene transcription (↓ IL-1, IL-6, TNF-α; ↑ lipocortin). Short plasma half-life (2–3 h) but 12–36 h biological effect. Pulse dosing (500–1000 mg IV) is used in severe autoimmune disease.',
   E'• Crises graves de asma e doença pulmonar obstrutiva\\n• Doenças autoimunes e reumáticas (lupus, vasculites, artrite reumatóide)\\n• Rejeição de transplantes (com outros imunossupressores)\\n• Edema cerebral (tumores) e esclerose múltipla em surto\\n• Doença inflamatória intestinal grave (Crohn, colite ulcerosa)',
   E'• Severe asthma attacks and obstructive pulmonary disease\\n• Autoimmune and rheumatic diseases (lupus, vasculitis, rheumatoid arthritis)\\n• Transplant rejection (with other immunosuppressants)\\n• Cerebral oedema (tumours) and multiple sclerosis relapse\\n• Severe inflammatory bowel disease (Crohn\u2019s, ulcerative colitis)',
   E'• Aumento do apetite, retenção de líquidos e ganho de peso\\n• Insónia, agitação e alteração do humor\\n• Hiperglicemia (cuidado em diabéticos)\\n• Hipertensão e edemas\\n• Em uso prolongado: osteoporose, cataratas, atrofia cutânea, imunossupressão, supressão da suprarrenal\\n• Psicose esteroidea (raro)\\n• Procure ajuda imediata se houver febre com mal-estar (risco de infeção) ou visão turva (catarata/glaucoma agudo).',
   E'• Increased appetite, fluid retention and weight gain\\n• Insomnia, agitation and mood change\\n• Hyperglycaemia (caution in diabetics)\\n• Hypertension and oedema\\n• With prolonged use: osteoporosis, cataracts, skin atrophy, immunosuppression, adrenal suppression\\n• Steroid psychosis (rare)\\n• Seek immediate help if fever with malaise (infection risk) or blurred vision (cataract/acute glaucoma) occurs.',
   E'• Nunca suspender bruscamente após uso > 2 semanas (insuficiência suprarrenal) — reduzir gradualmente\\n• Vigiar glicemia, tensão, potássio e peso\\n• Proteção gástrica (IPP) em dose alta ou com AINEs\\n• Em pulso IV: perfusão lenta (≥ 30 min) com monitorização (risco de arritmia/hipotensão)',
   E'• Never stop abruptly after > 2 weeks of use (adrenal insufficiency) — taper gradually\\n• Monitor glucose, blood pressure, potassium and weight\\n• Gastric protection (PPI) at high dose or with NSAIDs\\n• IV pulse: slow infusion (≥ 30 min) with monitoring (arrhythmia/hypotension risk)',
   E'Rótulo aprovado DailyMed/FDA — Methylprednisolone (ver também Depo-Medrol e Solumedrol; rótulo combinado Physicians EZ Use M-PRED valida a via): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=76b15f6a-51d6-45ec-b6cb-8b10a08ed32a — com referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)',
   E'DailyMed/FDA approved label — Methylprednisolone (see also Depo-Medrol and Solumedrol; combined label Physicians EZ Use M-PRED validates the pathway): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=76b15f6a-51d6-45ec-b6cb-8b10a08ed32a — with additional reference: Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012)')
) AS v(slug, overview_public_pt, overview_public_en, overview_pro_pt, overview_pro_en,
       indications_pt, indications_en, side_effects_pt, side_effects_en,
       precautions_pt, precautions_en, source_pt, source_en)
  ON d.slug = v.slug
ON CONFLICT (drug_id) DO NOTHING;
